const prompt = $json["prompt"] || "";
const projectPath = $json["project_path"] || "C:\\GitHub\\LLM_Pract";

// Parse the system prompt to extract requirements
const requirements = {
  quantizationAwareTraining: prompt.includes("Quantization-Aware Training (QAT)"),
  ternaryWeights: prompt.includes("1.58-bit weight structure") && prompt.includes("W ∈ {-1, 0, 1}"),
  lightningAttention: prompt.includes("Lightning Attention"),
  qaoaIntegration: prompt.includes("Quantum Approximate Optimization Algorithm (QAOA)"),
  syclOptimization: prompt.includes("Intel ARC SYCL"),
  moeExemption: prompt.includes("MoE gating network") && prompt.includes("exempted from ternarization"),
  hardwareOptimization: prompt.includes("SYCL DPAS lowering pass")
};

return {
  prompt,
  projectPath,
  requirements,
  timestamp: new Date().toISOString()
};

const requirements = $json["requirements"];
const projectPath = $json["projectPath"];

// Generate implementation plan based on requirements
const implementationPlan = {
  phases: [],
  filesToModify: [],
  newFiles: [],
  dependencies: []
};

// Phase 1: Quantization-Aware Training
if (requirements.quantizationAwareTraining) {
  implementationPlan.phases.push({
    name: "Quantization-Aware Training (QAT)",
    description: "Implement QAT pipeline with FP16 pre-training and 1.58-bit quantization",
    tasks: [
      "Create QAT training pipeline",
      "Implement FP16 optimizer state retention",
      "Add RMSNorm integration for Lightning Attention",
      "Create transition point handling"
    ]
  });

  implementationPlan.filesToModify.push(
    "qminiwasm/training/loop.py",
    "qminiwasm/layers/attention.py",
    "qminiwasm/layers/ternary.py"
  );
}

// Phase 2: Ternary Weight Structure
if (requirements.ternaryWeights) {
  implementationPlan.phases.push({
    name: "Ternary Weight Structure",
    description: "Implement 1.58-bit weight quantization with W ∈ {-1, 0, 1}",
    tasks: [
      "Enhance ternary quantization algorithm",
      "Implement 2-bit signed integer packing",
      "Add memory optimization for weight storage",
      "Create variance initialization for ternary parameters"
    ]
  });

  implementationPlan.newFiles.push(
    "qminiwasm/layers/ternary_quantization.py",
    "qminiwasm/optimization/ternary_optimizer.py"
  );
}

// Phase 3: Lightning Attention Fix
if (requirements.lightningAttention) {
  implementationPlan.phases.push({
    name: "Lightning Attention Fix",
    description: "Fix Lightning Attention with RMSNorm integration",
    tasks: [
      "Add RMSNorm before quantized linear projections",
      "Implement Q, K, V normalization",
      "Fix variance stabilization",
      "Add kernel φ application"
    ]
  });

  implementationPlan.filesToModify.push(
    "qminiwasm/layers/attention.py"
  );
}

// Phase 4: QAOA Integration
if (requirements.qaoaIntegration) {
  implementationPlan.phases.push({
    name: "Quantum QAOA Integration",
    description: "Integrate QAOA with classical STE training pipeline",
    tasks: [
      "Implement problem Hamiltonian H_C",
      "Create Neural Network-initialized QAOA protocol",
      "Add angle prediction for γ and β",
      "Implement quantum state injection"
    ]
  });

  implementationPlan.newFiles.push(
    "qminiwasm/quantum/qaoa_integration.py",
    "qminiwasm/quantum/problem_hamiltonian.py"
  );
}

// Phase 5: SYCL Hardware Optimization
if (requirements.syclOptimization) {
  implementationPlan.phases.push({
    name: "SYCL Hardware Optimization",
    description: "Implement custom SYCL DPAS lowering pass",
    tasks: [
      "Create SYCL DPAS lowering pass",
      "Implement memory packing for int2 blocks",
      "Add GRF bypassing configuration",
      "Replace joint_matrix_mad with dpas.int2.int8"
    ]
  });

  implementationPlan.filesToModify.push(
    "qminiwasm/hardware/sycl/sycl_hardware.py"
  );

  implementationPlan.newFiles.push(
    "qminiwasm/hardware/sycl/dpas_lowering.py",
    "qminiwasm/hardware/sycl/memory_packing.py"
  );
}

// Phase 6: MoE Router Exemption
if (requirements.moeExemption) {
  implementationPlan.phases.push({
    name: "MoE Router Exemption",
    description: "Exempt MoE gating network from ternarization",
    tasks: [
      "Identify MoE router components",
      "Implement FP8 precision for router",
      "Add quantum QAOA governance for router",
      "Create routing collapse prevention"
    ]
  });

  implementationPlan.filesToModify.push(
    "qminiwasm/quantum/router.py"
  );
}

// Phase 7: Hardware Orchestration
if (requirements.hardwareOptimization) {
  implementationPlan.phases.push({
    name: "Hardware Orchestration",
    description: "Optimize hardware orchestration for ternary weights",
    tasks: [
      "Implement memory packing in host memory",
      "Add 2D block load instructions",
      "Configure joint_matrix_load with SIMD control",
      "Bypass L1 data cache for weights"
    ]
  });

  implementationPlan.filesToModify.push(
    "qminiwasm/hardware/sycl/sycl_hardware.py"
  );
}

return {
  implementationPlan,
  projectPath,
  timestamp: new Date().toISOString()
};

const implementationPlan = $json["implementationPlan"];
const projectPath = $json["projectPath"];

// Create file modification tasks
const fileTasks = [];

// Process files to modify
for (const filePath of implementationPlan.filesToModify) {
  fileTasks.push({
    type: "modify",
    filePath: `${projectPath}/${filePath}`,
    description: `Update ${filePath} for ternary architecture`,
    priority: "high"
  });
}

// Process new files to create
for (const filePath of implementationPlan.newFiles) {
  fileTasks.push({
    type: "create",
    filePath: `${projectPath}/${filePath}`,
    description: `Create ${filePath} for ternary architecture`,
    priority: "medium"
  });
}

return {
  fileTasks,
  implementationPlan,
  projectPath,
  timestamp: new Date().toISOString()
};

