    def forward(self, x):
        norm = x.norm(dim=-1, keepdim=True)
        return self.weight * x / (norm + self.eps)

# Integration in attention layer
q_norm = RMSNorm(d_model)(q)
k_norm = RMSNorm(d_model)(k)
v_norm = RMSNorm(d_model)(v)`
      };
    }
  } else if (task.type === "create") {
